"""Operational panels reuse the existing map and signed-ledger forms."""
from .dashboard import esc
from .registry import FACILITY_TYPES,MEDICAL_TYPES


def camp_detail(camp,snapshot):
    actor=snapshot['node'];key=camp['id'];stock=snapshot['state']['stocks'].get(key);q=stock['on_hand'] if stock else 'Unknown';reserved=stock['reserved'] if stock else 0
    return f'''<section data-camp-detail="{key}" {'hidden' if key!=actor else ''}><h2>{esc(camp['name'])}</h2><h3 class="host-name">{esc(camp['host_name'])}</h3><p>{esc(camp['address'])}</p><p class="help">TEST host · permission: {esc(camp['permission_status'])} · point: {esc(camp['coordinate_status'])}</p><dl class="camp-status"><div><dt>On hand</dt><dd>{q}</dd></div><div><dt>Reserved</dt><dd>{reserved}</dd></div><div><dt>Capacity</dt><dd>{camp['capacity'] if camp['capacity'] is not None else 'Unknown'}</dd></div></dl><p>Signed supply origin: {key}. No A/B history reassigned.</p>{f'<a href="/?view=commitments&amp;camp={key}" data-explicit-camp>Operate {key} supplies</a>' if key in snapshot.get('actor_nodes',[c['id'] for c in snapshot['registry']['camps']]) else '<p>Remote camp · read-only signed profile</p>'}<hr><button {"disabled" if snapshot.get("local_camp") and key!=snapshot["local_camp"] else ""} data-edit-camp="{key}">Edit camp record</button><button {"disabled" if snapshot.get("local_camp") and key!=snapshot["local_camp"] else ""} data-draw="perimeter" data-camp="{key}">{'Edit' if camp['perimeter'] else 'Draw'} physical perimeter</button><button {"disabled" if snapshot.get("local_camp") and key!=snapshot["local_camp"] else ""} data-draw="service_area" data-camp="{key}">Edit service area</button><p class="help">Solid = physical footprint ({'drawn, operator assertion' if camp['perimeter'] else 'not drawn'}). Dashed = responsibility. Overlaps remain visible.</p><a href="/?view=facilities&amp;camp={key if key in snapshot.get("actor_nodes",[key]) else actor}" data-explicit-camp>Public infrastructure catalogue</a><p><a href="{esc(camp['source_url'])}" target="_blank" rel="noreferrer noopener">Location source</a></p></section>'''


def panel(snapshot,view):
    state=snapshot['state'];camp=snapshot['node']
    if view=='reports':return f'''<section class="page-heading"><h1>Reports requiring review</h1><p>Incoming claims remain unverified. Operator confirmation is not field proof.</p></section><details id="operator-report-entry" class="report-composer"><summary>Add report from this camp machine</summary><p>Drag the saved map beneath the fixed pin, then confirm the problem location. Coordinates and the acting camp point remain available. No location is assumed.</p><div id="operator-report-map" tabindex="0" role="group" aria-label="Report location map"></div><button type="button" id="report-map-centre">Confirm pin location</button><button type="button" id="report-camp-location">Use acting camp point</button>{report_form('operator-report-form')}<p id="operator-report-status" role="status"></p></details><a href="/?view=phone">Phone invitation and QR</a><div class="ops-columns"><section><label>Filter reports<select id="report-filter"><option value="active">Unverified / confirmed</option><option value="all">All reports</option></select></label><div id="report-list"></div></section><section id="report-detail" aria-live="polite">Select a report to review. Contacts stay off the map.</section></div>'''
    if view=='facilities':return '''<section class="page-heading"><h1>Public infrastructure</h1><p>Source candidates, not current availability or authorised shelters. Inside service area and nearby are distinct; distances are straight-line.</p></section><label>Search facilities<input id="facility-search" type="search" placeholder="Name or note"></label><label>Category<select id="facility-category"><option value="">All categories</option>'''+''.join(f'<option value="{x}">{esc(FACILITY_TYPES[x])}</option>' for x in FACILITY_TYPES)+'''</select></label><button id="add-facility">Add facility</button><p id="facility-count"></p><div id="facility-list"></div><button id="facility-more" hidden>Show 80 more</button>'''
    if view=='links':return '''<section class="page-heading"><h1>Camp connections</h1><p>The short camp ID stays the same across launches. Copy the full share code to another computer to transfer recorded geography offline. Coordinates and polygons are operator/source records, not a new survey.</p></section><p id="local-camp-id"></p><label>Full public camp share code<textarea id="local-camp-code" rows="4" readonly></textarea></label><button id="copy-camp-code">Copy share code</button><p id="camp-link-mode"></p><h2>Add or update another camp</h2><label>Paste its full share code<textarea id="peer-code" rows="4" maxlength="65536"></textarea></label><button id="preview-peer">Preview camp</button><pre id="peer-preview" style="white-space:pre-wrap;overflow-wrap:anywhere"></pre><label><input type="checkbox" id="confirm-peer-key">I compared the full public key with the source camp (or received it through its verified SSH channel).</label><button id="accept-peer" disabled>Pin camp identity and accept recorded geography</button><h2>Known camps</h2><pre id="known-peers" style="white-space:pre-wrap;overflow-wrap:anywhere"></pre><h2>SSH demonstration link</h2><p>One SSH connection exchanges signed requests and workflow statuses both ways every 15 seconds when enabled. Host keys must already be verified; use a restricted transport key. No password or private signing key is sent in the camp code. Phone reports/contacts and local route choices are not synchronized.</p><form id="ssh-config"><label>Host / IP<input name="host" required></label><label>SSH user<input name="user" required></label><label>SSH port<input name="port" type="number" min="1" max="65535" value="22" required></label><label>Remote SANJAY folder<input name="remote_path" placeholder="/home/user/SANJAY" required></label><label>Remote operator port<input name="remote_port" type="number" min="1" max="65535" value="8890" required></label><label><input name="enabled" type="checkbox">Enable automatic signed update exchange</label><button>Save SSH settings</button></form><button id="sync-peer">Sync now</button><p id="sync-peer-status" role="status"></p>'''
    if view=='network':return '''<section class="page-heading"><h1>Camp Wi-Fi</h1><p>This machine broadcasts the camp network. Join its Wi-Fi, then use the network sign-in window for local reporting. No internet tunnel or phone security changes.</p></section><p class="notice">Experimental captive-portal mode. Safari/Chrome HTTPS-only navigation is not bypassed; automatic sign-in must be checked on the actual phone. Keep this app running.</p><p id="network-status" role="status">Checking Windows hotspot…</p><button id="network-start">Start camp Wi-Fi and portal</button><button id="network-stop">Stop camp Wi-Fi</button><button id="network-refresh">Refresh status</button><h2>Join the camp network</h2><p>Scan this Wi-Fi QR with the phone camera. This joins Wi-Fi; it is not a web link.</p><img id="network-qr" width="256" height="256" alt="Private QR to join camp Wi-Fi" style="background:white"><p>No sign-in popup? Open the Wi-Fi network details and use Join Network / Log In if offered. Do not disable HTTPS protections. This Windows implementation still needs a physical-phone test; Pi setup remains pending.</p>'''
    if view=='phone':return '''<section class="page-heading"><h1>Phone reporting</h1><p>Connect phones to this laptop's trusted Wi-Fi. Invitation permits submission only, never stock or report-list access.</p></section><p id="phone-link"></p><img id="phone-qr" alt="QR for temporary phone invitation" width="256" height="256"><p id="invite-expiry"></p><button id="rotate-invite">Revoke old invitation and create new</button><p>Plain LAN HTTP is not encrypted. Avoid personal details. GPS may be blocked; drag the saved map beneath the pin instead. Firewall must permit this submission port on the private network; SANJAY does not change firewall rules.</p>'''
    if view=='routes':
        approved=[(key,g) for key,g in state['grants'].items() if g['supplier']==camp and g['status']=='approved']
        options=''.join(f'<option value="{key}">{key[:8]} · {g["quantity"]} packets</option>' for key,g in approved)
        destinations=''.join(f'<option value="{c["id"]}">{esc(c["name"])}</option>' for c in snapshot['registry']['camps'] if c['id']!=camp)
        return f'''<section class="page-heading"><h1>Offline road options</h1><p>Acting supplier: {camp}. Car profile, not truck clearance, flood detection or verified passability.</p></section><form id="route-form"><label>Approved allocation<select name="grant_id"><option value="">Preview only (no dispatch choice)</option>{options}</select></label><label>Preview destination<select name="destination">{destinations}</select></label><button>Calculate saved-road alternatives</button></form><div id="route-results" aria-live="polite"></div>'''
    return ''


def medical_legend():
    items=''.join(f'<li><svg aria-hidden="true" class="facility-symbol"><use href="/assets/facility-icons.svg#{key}"></use></svg>{esc(FACILITY_TYPES[key])}</li>' for key in MEDICAL_TYPES)
    return '<details class="facility-legend"><summary>Medical facility symbols</summary><ul>'+items+'</ul><p>Type only: not verified beds, staff, medicine stocks, accessibility or current availability.</p></details>'


def editor():
    return '''<dialog id="record-editor"><form id="record-form"><h2 id="editor-title"></h2><div id="editor-fields"></div><p id="editor-error" role="alert"></p><button type="submit">Save record</button><button type="button" id="cancel-editor">Cancel</button></form></dialog><section id="drawing-tools" hidden aria-label="Boundary editor"><strong id="drawing-label"></strong><p>Click map to add vertices; drag handles to move them. Keyboard: pan map with arrows, then Add map centre. GeoJSON is editable below.</p><button id="draw-centre">Add map centre</button><button id="draw-undo">Undo last vertex</button><button id="draw-save">Save boundary</button><button id="draw-cancel">Cancel without saving</button><label>GeoJSON geometry<textarea id="drawing-json" rows="4"></textarea></label><button id="draw-apply">Apply coordinates to preview</button><p id="drawing-error" role="alert"></p></section>'''


def report_form(form_id):
    return f'''<form id="{form_id}"><label>Latitude<input name="lat" type="number" min="-90" max="90" step="any" required></label><label>Longitude<input name="lon" type="number" min="-180" max="180" step="any" required></label><label>Problem<select name="category"><option value="road_obstruction">Road obstruction</option><option value="water">Water problem</option><option value="medical">Medical need</option><option value="supply">Supply need</option><option value="other">Other</option></select></label><label>Reported severity<select name="severity"><option value="unknown">Unknown</option><option value="moderate">Moderate</option><option value="high">High</option><option value="critical">Critical</option></select></label><label>Description<textarea name="description" maxlength="1500" required></textarea></label><label>Optional contact, private to operator<input name="reporter_contact" maxlength="150" autocomplete="off"></label><p>Trusted Wi-Fi only: HTTP is unencrypted. Avoid personal or medical details. Contact is stored locally, not displayed on maps.</p><button>Submit for review</button></form>'''


def phone_page(csrf,ticket):
    return f'''<!doctype html><html lang="en" data-theme="dark"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf-token" content="{csrf}"><meta name="form-ticket" content="{ticket}"><title>SANJAY · Report a problem</title><link rel="icon" href="data:,"><link rel="stylesheet" href="/assets/app.css"><link rel="stylesheet" href="/assets/ops.css"><link rel="stylesheet" href="/assets/leaflet/leaflet.css"><script nonce="{csrf}" src="/assets/leaflet/leaflet.js" defer></script><script nonce="{csrf}" src="/assets/location-picker.js" defer></script><script nonce="{csrf}" src="/assets/phone.js" defer></script></head><body class="phone-page"><main><h1>Report a local problem</h1><p>This is a test portal, not an emergency hotline. Reports require operator review.</p><div id="phone-map" tabindex="0" aria-label="Drag map beneath fixed pin to choose report location"></div><button id="phone-centre">Confirm pin location</button><button id="phone-gps">Use phone GPS (if permitted)</button><p id="phone-status" role="status">Drag the map beneath the pin, then confirm the location. No location is assumed.</p>{report_form('phone-form')}</main></body></html>'''
